  createAsset: {
    parameters: {
      query?: never;
      header?: never;
      path?: never;
      cookie?: never;
    };
    /** @description Send the metadata part before the file part. The file is read as it arrives, so the catalog fields have to be known by then. */
    requestBody: {
      content: {
        "multipart/form-data": {
          metadata: components["schemas"]["CreateAssetRequest"];
          /** Format: binary */
          file: string;
        };
        "application/json": components["schemas"]["StartAssetRequest"];
      };
    };
    responses: {
      /** @description The draft that was started, with the blocks its kind requires */
      201: {
        headers: {
          Location?: string;
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["AssetDetail"];
        };
      };
      /** @description The durable ingest operation for the accepted upload */
      202: {
        headers: {
          Location?: string;
          [name: string]: unknown;
        };
        content: {
          "application/json": components["schemas"]["IngestOperation"];
        };
      };
      /** @description No account is signed in */
      401: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description The signed-in account has not verified its email */
      403: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description The file exceeds an upload limit or the account storage cap */
      413: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description The uploaded bytes have been purged and cannot return */
      422: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
      /** @description The storage reserve cannot accept the upload */
      503: {
        headers: {
          [name: string]: unknown;
        };
        content?: never;
      };
    };
  };
